/* style.css — the look of Duel Arkanum: a dark green felt table, gold trim,
   and cards that read at a glance. Every colour comes from here; no font
   or image is loaded from the network, only system fonts. */

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
  background: #12291c;
  color: #f3ead3;
  font-family: Georgia, 'Times New Roman', serif;
}

#app {
  max-width: 1180px;
  margin: 0 auto;
  padding: 10px 16px 20px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ---- top bar ---- */
.topbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 6px 4px;
  border-bottom: 2px solid #c9a227;
}

.game-title {
  font-size: 26px;
  font-weight: bold;
  letter-spacing: 2px;
  color: #ffd75e;
  text-shadow: 0 2px 0 #6b4e00;
  white-space: nowrap;
}

#turn-badge {
  flex: 1;
  text-align: center;
  font-size: 18px;
  font-weight: bold;
  color: #bfe3c6;
}

.topbar button, .big-btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: bold;
  color: #241a05;
  background: linear-gradient(#ffe27a, #e8b93b);
  border: 2px solid #8a6d00;
  border-radius: 8px;
  padding: 8px 14px;
  cursor: pointer;
}

.topbar button:hover, .big-btn:hover { filter: brightness(1.08); }
.topbar button:disabled { opacity: 0.45; cursor: default; }

#end-turn {
  min-width: 210px;
  font-size: 16px;
}

/* ---- hero panels ---- */
.hero {
  display: flex;
  gap: 12px;
  align-items: center;
  background: #1d3a28;
  border: 2px solid #c9a227;
  border-radius: 12px;
  padding: 10px 14px;
  min-width: 430px;
}

.hero .avatar {
  font-size: 46px;
  line-height: 1;
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0f2117;
  border: 2px solid #c9a227;
  border-radius: 50%;
}

.hero-info { flex: 1; }
.hero-name { font-size: 19px; font-weight: bold; color: #ffe9a8; }
.hero-title { font-size: 13px; color: #a8c8ae; margin-bottom: 6px; }

.life { display: flex; align-items: center; gap: 8px; }
.life-bar {
  flex: 1;
  height: 16px;
  background: #0a1a10;
  border: 1px solid #55705a;
  border-radius: 8px;
  overflow: hidden;
}
.life-fill { height: 100%; background: linear-gradient(#ff7a6b, #d21f1f); }
.life-fill.low { background: linear-gradient(#ffb13d, #d21f1f); }
.life-text { font-size: 16px; font-weight: bold; white-space: nowrap; }

.mana { display: flex; align-items: center; gap: 2px; margin-top: 4px; }
.mana .pip { font-size: 13px; color: #3c5a45; }
.mana .pip.filled { color: #4fc3f7; text-shadow: 0 0 6px #4fc3f7; }
.mana .pip.locked { opacity: 0.35; }
.mana-label { font-size: 13px; color: #9fd0ff; margin-left: 6px; }
.deck-count { font-size: 13px; color: #c8b98a; margin-top: 3px; }

/* ---- zones ---- */
#ai-zone, #player-zone {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.hand-backs {
  display: flex;
  gap: 4px;
  padding-top: 8px;
  min-width: 120px;
  flex-wrap: wrap;
}

.board-row, #player-hand {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: flex-start;
  flex: 1;
}

#player-board { min-height: 150px; }
#ai-board { min-height: 150px; }

.board-empty {
  color: #7fa386;
  font-style: italic;
  padding: 56px 10px;
}

#mid-bar {
  display: flex;
  gap: 16px;
  align-items: center;
  background: #0f2117;
  border: 1px solid #3c5a45;
  border-radius: 8px;
  padding: 6px 12px;
}

#log { flex: 1; font-size: 14px; color: #cfe3d2; }
.log-line { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#hint { font-size: 13px; color: #ffd75e; max-width: 46%; text-align: right; }

#player-hero-box { display: flex; }

/* ---- cards ---- */
.card {
  width: 128px;
  min-height: 168px;
  background: #f8f1de;
  color: #241a05;
  border: 3px solid var(--el, #7a6a58);
  border-radius: 10px;
  padding: 6px 7px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.45);
  cursor: default;
  user-select: none;
}

#player-hand .card { cursor: pointer; }
#player-board .card { cursor: pointer; }
#ai-board .card { cursor: pointer; }

.card-head { display: flex; justify-content: space-between; font-size: 14px; font-weight: bold; }
.card-head .cost {
  background: #2b7fd4;
  color: #fff;
  border-radius: 50%;
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
}
.card-head .element { font-size: 13px; }

.card-name { font-size: 15px; font-weight: bold; text-align: center; }
.card-art {
  font-size: 40px;
  text-align: center;
  background: var(--el-soft, #ece5da);
  border-radius: 8px;
  padding: 6px 0;
}
.card-text { font-size: 12px; font-style: italic; text-align: center; flex: 1; }
.card-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 16px;
  font-weight: bold;
  border-top: 1px solid #d8cdb2;
  padding-top: 4px;
}
.card-foot .atk { color: #b3261e; }
.card-foot .hp { color: #1e7b34; }
.card-foot .sick { font-size: 13px; }
.card-foot .ready { font-size: 12px; color: #1e7b34; }
.spell-tag { font-size: 13px; color: #5b4a8a; }
.spell-amount { font-size: 15px; }

.card.playable { outline: 3px solid #ffd75e; }
.card.playable:hover { transform: translateY(-6px); }
.card.selected { outline: 4px solid #ff8c1a; transform: translateY(-6px); }
.card.targetable { outline: 3px dashed #ff5a4e; cursor: crosshair; }
.card.dimmed { opacity: 0.55; }

.card-back {
  width: 34px;
  height: 48px;
  background: repeating-linear-gradient(45deg, #7a1f1f, #7a1f1f 6px, #9c2b2b 6px, #9c2b2b 12px);
  border: 2px solid #e8b93b;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.back-glyph { font-size: 18px; color: #ffe9a8; }

/* ---- overlays ---- */
.overlay {
  position: fixed;
  inset: 0;
  background: rgba(8, 20, 12, 0.88);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}
.overlay.hidden { display: none; }

.overlay-card {
  background: #1d3a28;
  border: 3px solid #c9a227;
  border-radius: 16px;
  padding: 28px 36px;
  max-width: 620px;
  text-align: center;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.6);
}

.overlay-card h1 { font-size: 44px; color: #ffd75e; margin: 0 0 6px; letter-spacing: 3px; }
.overlay-card h2 { font-size: 20px; color: #bfe3c6; margin: 0 0 14px; font-weight: normal; }
.overlay-card p { font-size: 16px; line-height: 1.5; }
.rules { text-align: left; font-size: 15px; line-height: 1.7; margin: 12px auto; max-width: 480px; }
.big-btn { font-size: 20px; padding: 12px 30px; margin-top: 10px; }
.end-title { font-size: 52px; margin: 0 0 8px; }
.end-title.win { color: #ffd75e; }
.end-title.lose { color: #ff7a6b; }
#end-sub { font-size: 18px; }
#end-stats { font-size: 14px; color: #c8b98a; }
.keys { font-size: 13px; color: #a8c8ae; margin-top: 14px; }
```
